document.addEventListener('DOMContentLoaded',()=>{
  const activities=[
    {n:6,title:'Picture Dictionary Recall',mode:'TEAM PAIRS',page:'REVIEW',mins:5,objective:'Recall key ideas from Part 1.',keywords:['noise','homesick','friendship','teamwork'],instruction:'Match each mixed picture with the correct word. Discuss first, then reveal one match at a time.',images:[],steps:['Read the mixed word bank.','Study each numbered picture.','Agree on one word for each picture.','Reveal and check one picture at a time.'],special:'p2pictures'},
    {n:7,title:'Collocations in Context',mode:'PAIR WORK',page:'12',mins:10,objective:'Complete common collocations accurately.',keywords:['take part','make arrangements','have fun','do research','make progress'],instruction:'Complete Activity 7 with do, make, take or have. Check one sentence at a time and notice the verb tense.',images:['part2-activity7.png'],labels:['Book Activity 7 · Page 12'],bookAnswers:[['1 · took part','2 · is making arrangements','3 · made an excuse','4 · have an appointment','5 · have a break','6 · is doing research','7 · take a test','8 · have fun','9 · do you good','10 · make great progress','11 · take a break','12 · do me a favor']],steps:['Read each complete sentence for context.','Choose do, make, take or have.','Change the tense when necessary.','Reveal and correct one answer at a time.'],special:'p2a7'},
    {n:8,title:'Reading Vocabulary Review',mode:'INDIVIDUAL → PAIR',page:'13',mins:10,objective:'Match housing terms with their meanings.',keywords:['dormitory','amenities','special-interest housing','survive','short form'],instruction:'Use the word box to complete Activity 8. Then finish the three short forms.',images:['part2-activity8.png'],labels:['Book Activity 8 · Page 13'],bookAnswers:[['1 · dormitory','2 · amenities','3 · special-interest housing','4 · survive','5 · dormitory','6 · higher education','7 · cooperative']],steps:['Read each definition carefully.','Choose the most precise term.','Complete the short forms.','Reveal and check one answer at a time.'],special:'p2a8'},
    {n:9,title:'Words with Related Meanings',mode:'GROUP WORK',page:'13',mins:14,objective:'Identify and explain related word groups.',keywords:['related meanings','odd word','similar','explain'],instruction:'Study Activity 9 in three separate parts. Cross out the word that does not belong, then explain the relationship.',images:['part2-activity9-intro.png','part2-activity9-a.png','part2-activity9-b.png'],labels:['Activity 9 · Instructions & Example','Activity 9 · Questions 2–4','Activity 9 · Questions 5–8'],bookAnswers:[null,['2 · educational events','3 · privacy','4 · participation'],['5 · academically','6 · valuable','7 · high-paying','8 · exercise']],steps:['Study the completed example.','Find three words with related meanings.','Cross out the unrelated word.','Explain how the remaining words are similar.','Move through all three book parts.'],special:'p2a9'},
    {n:10,title:'Campus Word Quest',mode:'TEAM GAME',page:'EXIT',mins:6,objective:'Review Part 2 in a team challenge.',keywords:['collocation','definition','related meaning','evidence'],instruction:'Teams answer five questions. Reveal one answer, award a point, then move to the next card.',images:[],steps:['Divide the class into groups.','Choose one speaker per question.','Answer before revealing.','Award one point for a correct explanation.'],special:'p2exit'}
  ];
  window.part2Activities=activities;
  const cards=document.getElementById('cards2');
  cards.innerHTML=activities.map((a,i)=>`<button class="card" data-num="${a.n}" onclick="openActivity(${a.n})"><span class="pill">${a.mode}</span><h3>${i+1}. ${a.title}</h3><p>${a.objective}</p><span class="page">${a.page==='EXIT'?'EXIT TICKET':a.page==='REVIEW'?'PART 1 REVIEW':'BOOK PAGE '+a.page} · ${a.mins} MIN</span></button>`).join('');
  activities.forEach(a=>document.getElementById('activities').insertAdjacentHTML('beforeend',activityHTML(a)));
  activities.forEach(a=>{initTimer(document.querySelector(`#a${a.n} .timer`),a.mins*60);if(a.images.length)moveBookPart(a.n,0)});
  initPart2Specials();
  document.getElementById('planlink2').onclick=()=>openPlanPart2(activities);
  document.querySelectorAll('.partswitch button').forEach(b=>b.onclick=()=>switchLessonPart(+b.dataset.part));
  if(new URLSearchParams(location.search).get('part')==='2')switchLessonPart(2);
});

function switchLessonPart(part){document.querySelectorAll('.partswitch button').forEach(b=>b.classList.toggle('active',+b.dataset.part===part));document.querySelectorAll('.part1only').forEach(x=>x.hidden=part!==1);document.querySelectorAll('.part2only').forEach(x=>x.hidden=part!==2);window.scrollTo({top:0,behavior:'smooth'})}

function initPart2Specials(){
  const pics=document.querySelector('#a6 .special');
  pics.innerHTML=`<h2>Match the Mixed Pictures</h2><div class="p2wordbank"><span>homesick</span><span>teamwork</span><span>noise</span><span>friendship</span></div><div class="picturedictionary">${[[4,'teamwork'],[1,'noise'],[3,'friendship'],[2,'homesick']].map((x,i)=>`<article class="picturecard" data-scene="${x[0]}"><div class="picturethumb" role="img" aria-label="Picture ${i+1}"></div><footer><b>Picture ${i+1}</b><button class="reveal">Reveal Word</button></footer><div class="answer">${x[1]}</div></article>`).join('')}</div>`;pics.querySelectorAll('.reveal').forEach(b=>b.onclick=()=>{const a=b.closest('.picturecard').querySelector('.answer');a.classList.toggle('show');b.textContent=a.classList.contains('show')?'Hide Word':'Reveal Word'});
  initDeck('#a7 .special',[
    ['They ___ part in many campus activities last year.','took'],['She ___ arrangements for the theater this weekend.','is making'],['He ___ an excuse about being ill.','made'],['I ___ an appointment at 8 a.m.','have'],['Can I ___ a break before lunch?','have'],['Robert is ___ research now.','doing'],['Will you ___ a test before summer?','take'],['It is good to ___ fun sometimes.','have'],['Walking every day will ___ you good.','do'],['You helped me ___ great progress.','make'],['They decided to ___ a break.','take'],['Can you ___ me a favor?','do']]);
  initDeck('#a8 .special',[
    ['A building with rooms for residents and shared facilities.','dormitory'],['Features that provide comfort or luxury.','amenities'],['Housing for residents with the same major, lifestyle or background.','special-interest housing'],['Get through without harm.','survive'],['Complete the short form: dorm___.','dormitory'],['Complete the short form: higher ed___.','higher education'],['Complete the short form: housing co-op___.','housing cooperative']]);
  initDeck('#a9 .special',[
    ['Dormitory · recreational facilities · residence hall · campus housing','Cross out recreational facilities. The others are places to live at university.'],['furnished rooms · accommodations · educational events · places to live','Cross out educational events. The others refer to housing.'],['privacy · strangers · unfamiliar people · occupants of other buildings','Cross out privacy. The others refer to people residents may not know.'],['challenges · problems · trouble · participation','Cross out participation. The others refer to difficulties.'],['academically · terrible · unpleasant · miserable','Cross out academically. The others describe negative experiences.'],['homesick · isolated · valuable · lonely','Cross out valuable. The others describe feeling alone or unhappy.'],['waste · lose · high-paying · use up','Cross out high-paying. The others mean something is spent or gone.'],['exercise · dangerous · harmful · unsafe','Cross out exercise. The others describe risk.']]);
  initDeck('#a10 .special',[
    ['Complete: Students ___ part in campus activities.','take'],['Which word means features for comfort or luxury?','amenities'],['Which does not belong: homesick, isolated, valuable, lonely?','valuable'],['What is the full form of “housing co-op”?','housing cooperative'],['Team Challenge: Use one collocation and one housing word in a meaningful sentence.','Example: We took part in an event at our residence hall.']]);
  moveSpecialToCanvas(6);
  moveSpecialToCanvas(10);
}

function moveSpecialToCanvas(n){const section=document.getElementById('a'+n),canvas=section.querySelector('.gamevisual'),activity=section.querySelector('.special');canvas.innerHTML='';canvas.className='activitycanvas';canvas.appendChild(activity)}

function initDeck(selector,cards){const root=document.querySelector(selector);let i=0;root.innerHTML='<div class="questiondeck"><div class="counter">Question <span>1</span> of '+cards.length+'</div><h2></h2><button class="reveal">Reveal Answer</button><div class="answer"></div><div class="decknav"><button class="prev">← Previous</button><button class="next">Next →</button></div></div>';const draw=()=>{root.querySelector('.counter span').textContent=i+1;root.querySelector('h2').textContent=cards[i][0];root.querySelector('.answer').textContent=cards[i][1];root.querySelector('.answer').classList.remove('show');root.querySelector('.reveal').textContent='Reveal Answer';root.querySelector('.prev').disabled=i===0;root.querySelector('.next').disabled=i===cards.length-1};root.querySelector('.reveal').onclick=e=>{const a=e.currentTarget.nextElementSibling;a.classList.toggle('show');e.currentTarget.textContent=a.classList.contains('show')?'Hide Answer':'Reveal Answer'};root.querySelector('.prev').onclick=()=>{if(i){i--;draw()}};root.querySelector('.next').onclick=()=>{if(i<cards.length-1){i++;draw()}};draw()}

function openPlanPart2(A){
  document.getElementById('liveplan')?.remove();const link='https://saidahkhwar11-lang.github.io/Interactive-English-Lessons/Term-1/Grade-10/dist/?part=2',next=new Date(Date.now()+86400000),day=new Intl.DateTimeFormat('en-GB',{weekday:'long',timeZone:'Asia/Dubai'}).format(next),date=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dubai'}).format(next);
  const objectives=['Use common collocations accurately.','Match key terms with their meanings.','Group words with related meanings.','Explain vocabulary relationships clearly.'];
  const data=A.map((a,i)=>({title:`${i+1}. ${a.title}`,badge:(a.page==='EXIT'?'EXIT TICKET':a.page==='REVIEW'?'PART 1 REVIEW':'BOOK PAGE '+a.page)+' · '+a.mins+' MIN',mode:a.mode,objective:a.objective,instruction:a.instruction,steps:a.steps}));const block=a=>`<article class="schoolactivity"><h3>${a.title} <em>${a.badge}</em></h3><p><b>Type:</b> ${a.mode}</p><p><b>Procedure:</b> ${a.instruction}</p><ol>${a.steps.map(x=>`<li>${x}</li>`).join('')}</ol><p><b>Teacher’s Role:</b> Display, model, guide, monitor and give feedback.</p><p><b>Students’ Role:</b> Match, complete, explain and justify answers.</p><p><b>Purpose:</b> ${a.objective}</p></article>`;const starter=data[0],main=data.slice(1,-1),plenary=data.at(-1),modal=document.createElement('section');
  modal.id='liveplan';modal.className='liveplan schoolplan';modal.innerHTML=`<div class="plancontrols"><button class="planprint">Print / Save Part 2 PDF</button><button class="planclose">Close ✕</button></div><div class="schoolpage"><div class="academicyear"><span>العام الأكاديمي</span><b>2026–2027</b></div><table class="schooltable details"><tr><th>التاريخ<br>Date:</th><td>${day} · ${date}</td><th>المادة الدراسية<br>Subject</th><td>English</td><th>المعلم<br>Teacher(s)</th><td>Saidah Khwar</td><th>عنوان الدرس<br>Lesson #</th><td>Reading 2 · Part 2</td></tr><tr><th>موضوع الدرس<br>Lesson Topic</th><td colspan="2"><b class="plantopictitle">Unique Housing — Language Review</b><br><a class="lessonlink" href="${link}" target="_blank" rel="noopener">Open Interactive Lesson ↗</a></td><th>مخرجات التعلم<br>Key Learning Objective(s)</th><td colspan="4"><ul>${objectives.map(x=>`<li>Students will be able to ${x.charAt(0).toLowerCase()+x.slice(1)}</li>`).join('')}</ul></td></tr><tr><th>سؤال مهارات التفكير العليا<br>H.O.T. Question(s)</th><td colspan="7">How can understanding word partnerships and word relationships make your English clearer and more natural?</td></tr><tr><th>المفردات الجديدة<br>Keywords/New Vocabulary</th><td colspan="7">collocation · amenities · dormitory · special-interest housing · survive · privacy · isolated</td></tr><tr class="sectionrow"><th colspan="8">Lesson’s Procedures · سير الدرس</th></tr><tr><th>معايير النجاح<br>Success Criteria</th><td colspan="7">By the end of the lesson, students can complete collocations, define housing vocabulary and explain related word groups.</td></tr></table></div><div class="schoolpage"><div class="academicyear"><span>العام الأكاديمي</span><b>2026–2027</b></div><table class="schooltable procedures"><tr><th class="stage">التهيئة الحافزة<br>Warm up/Starter</th><td colspan="4">${block(starter)}</td><td class="timing">5 min</td></tr><tr><th>التطبيق الإلكتروني المستخدم<br>E-Implementation Tool</th><th class="level"></th><th>الفروق الفردية<br>Differentiation</th><th colspan="2">الاستراتيجيات المستخدمة لتحقيق مخرج التعلم<br>Main Activities linked to LO · AFL Strategy</th><th>التوقيت<br>Timing</th></tr><tr><td rowspan="3">Interactive lesson webpage<br>DataShow / Smart Board</td><td class="high">H</td><td><b>High:</b> Explain relationships and create original collocation sentences independently.</td><td rowspan="3" colspan="2" class="mainactivities"><h3>Main Activities</h3>${main.map(block).join('')}</td><td rowspan="3">34 min</td></tr><tr><td class="medium">M</td><td><b>Medium:</b> Use pair discussion, definitions and context clues.</td></tr><tr><td class="low">L</td><td><b>Low:</b> Use pictures, word banks, separated book parts and guided reveals.</td></tr><tr><th>الختام<br>Plenary</th><td colspan="4">${block(plenary)}</td><td class="timing">6 min</td></tr><tr><th colspan="2">متعلمون مستقلون<br>Independent Learners</th><td colspan="2"><b class="skillhit">Critical Thinking</b> · Self-Learning · <b class="skillhit">Clear Communication</b> · Positive Interactions · <b class="skillhit">Collaboration</b> · Real World Connections</td><th colspan="2">Learning Skills (please highlight)</th></tr><tr><th colspan="2">ربط مع مواد أخرى<br>Cross Curricular</th><td colspan="4"><b>Study Skills:</b> Categorizing, using context and recognizing meaningful language patterns.</td></tr><tr><th colspan="2">تعزيز ثقافة دولة الإمارات العربية المتحدة<br>UAE Culture and Heritage (UAE Vision 2031)</th><td colspan="4">Develops communication, cooperation and confident lifelong learning in a diverse UAE community.</td></tr></table><footer>Lesson Plan · Part 2 · Generated automatically from the current live lesson</footer></div>`;document.body.appendChild(modal);document.body.style.overflow='hidden';modal.querySelector('.planclose').onclick=()=>{modal.remove();document.body.style.overflow=''};modal.querySelector('.planprint').onclick=()=>window.print();
}
